import json, hashlib
from pathlib import Path

cwd = Path(r"D:\RamanLab\LabAgents\pi")
audit_id = "coord-audit-autofocus-current-position-20260624-007"
subject = {"id": "current-raman-sample", "kind": "user_sample", "label": "current Raman sample"}
plan = {"kind": "points", "points": [{"xUm": 983.351, "yUm": 1589.433, "zUm": 2188.975}]}

def stable(value):
    if value is None:
        return "null"
    if isinstance(value, str):
        return json.dumps(value, separators=(",", ":"))
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return json.dumps(value, separators=(",", ":"))
    if isinstance(value, list):
        return "[" + ",".join(stable(v) for v in value) + "]"
    if isinstance(value, dict):
        return "{" + ",".join(json.dumps(k, separators=(",", ":")) + ":" + stable(value[k]) for k in sorted(value)) + "}"
    return "null"

coordinate_hash = hashlib.sha256(stable({"subject": subject, "plan": plan}).encode()).hexdigest()
record = {
    "schemaVersion": "1",
    "coordinateAuditId": audit_id,
    "createdAt": "2026-06-24T10:30:00.000Z",
    "observedAt": "2026-06-24T10:29:00.000Z",
    "subject": subject,
    "plan": plan,
    "coordinatePlanHash": coordinate_hash,
    "approval": {
        "approvalId": "AF-20260624-ZZ-007-coordinate-audit",
        "operator": "zz",
        "approved": True,
        "notes": "Operator zz approved current COM17 MC.Newton readback coordinates for autofocus retry with longer LabSpec frame timeout. No Raman spectrum acquisition requested."
    },
    "notes": "Autofocus retry coordinate audit from COM17 readback: x=983.351, y=1589.433, z=2188.975 um; intended bounded Z autofocus window 2178.975-2198.975 um."
}
out = cwd / ".pi" / "experiment-runs" / "lab" / "coordinate-audits" / f"{audit_id}.json"
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(json.dumps(record, indent=2) + "\n", encoding="utf-8")
print(json.dumps({"path": str(out), "coordinateAuditId": audit_id, "coordinatePlanHash": coordinate_hash}, indent=2))

