"""AutofocusController - top-level orchestrator for single-point autofocus."""

import logging
import statistics
from typing import Callable, Optional
from autofocus.models import (
    ROI, FrameProvider, ZStage, FocusStrategy,
    AutofocusParams, FocusPoint, ScanCurve, FocusStatus, FocusResult,
)
from autofocus.exceptions import (
    OutOfRangeError, StageTimeoutError, FrameTimeoutError,
)
from autofocus.scanner import ZScanner
from autofocus.metrics import MetricStrategy
from stage.exceptions import StageError

log = logging.getLogger(__name__)


class AutofocusController:
    """High-level autofocus orchestrator: validates inputs, runs scans, applies confidence checks."""

    def __init__(
        self,
        stage: ZStage,
        frames: FrameProvider,
        strategy: Optional[FocusStrategy] = None,
    ):
        self.stage = stage
        self.frames = frames
        self._strategy = strategy

    def _result_error(
        self,
        status: FocusStatus,
        message: str,
        coarse: Optional[ScanCurve] = None,
        fine: Optional[ScanCurve] = None,
    ) -> FocusResult:
        """Build and log a failed FocusResult."""
        log.warning("Autofocus aborted: %s - %s", status.value, message)
        return FocusResult(
            status=status, z_best_um=None, final_score=None,
            confidence=0.0, coarse=coarse, fine=fine, message=message,
        )

    def run_single(
        self,
        roi: ROI,
        params: AutofocusParams,
        on_progress: Optional[Callable[[FocusPoint], None]] = None,
    ) -> FocusResult:
        """Run a full coarse->fine autofocus and return the outcome."""
        # 1. Resolve strategy and build scanner.
        strategy = self._strategy or MetricStrategy(params.metric_name)
        scanner = ZScanner(self.stage, self.frames, strategy, params)

        # 2. Read starting position; check overall reachability.
        try:
            z0 = self.stage.get_position_um()
        except (StageTimeoutError, StageError) as e:
            return self._result_error(FocusStatus.STAGE_ERROR, f"Cannot read Z position: {e}")
        if (z0 + params.coarse_range_um < params.z_min_um
                or z0 - params.coarse_range_um > params.z_max_um):
            return self._result_error(
                FocusStatus.OUT_OF_RANGE,
                f"Coarse range around z0={z0} does not overlap [{params.z_min_um}, {params.z_max_um}]",
            )

        # 3. Coarse scan.
        try:
            coarse = scanner.coarse_scan(z0, roi, on_progress=on_progress)
        except FrameTimeoutError as e:
            return self._result_error(FocusStatus.FRAME_ERROR, f"Coarse scan: {e}")
        except (StageTimeoutError, StageError) as e:
            return self._result_error(FocusStatus.STAGE_ERROR, f"Coarse scan: {e}")
        except OutOfRangeError as e:
            return self._result_error(FocusStatus.OUT_OF_RANGE, f"Coarse scan: {e}")

        # 4. Validate coarse curve.
        if len(coarse.points) < 3:
            return self._result_error(
                FocusStatus.NO_PEAK,
                "Too few coarse scan points to find a peak; widen z_min/z_max or check stage limits.",
                coarse=coarse,
            )
        coarse_scores = [p.score for p in coarse.points]
        argmax_index = max(range(len(coarse.points)), key=lambda k: coarse_scores[k])
        if argmax_index == 0 or argmax_index == len(coarse.points) - 1:
            return self._result_error(
                FocusStatus.NO_PEAK,
                "Peak likely outside coarse range, consider widening coarse_range_um.",
                coarse=coarse,
            )
        median_score = statistics.median(coarse_scores)
        prominence = (coarse_scores[argmax_index] - median_score) / (median_score + 1e-9)
        if prominence < params.coarse_min_prominence:
            return self._result_error(
                FocusStatus.NO_PEAK,
                "Focus curve too flat - likely low texture; try a different ROI.",
                coarse=coarse,
            )
        top3 = sorted(coarse.points, key=lambda p: p.score, reverse=True)[:3]
        low_confidence_saturation = any(
            p.saturation_ratio > params.max_saturation_ratio for p in top3
        )

        # 5. Re-centre fine scan on the raw argmax, not the parabolic estimate.
        zc = coarse.best().z_um

        # 6. Fine scan.
        try:
            fine = scanner.fine_scan(zc, roi, on_progress=on_progress)
        except FrameTimeoutError as e:
            status = FocusStatus.FRAME_ERROR
            return self._result_error(status, f"Fine scan: {e}", coarse=coarse)
        except (StageTimeoutError, StageError) as e:
            return self._result_error(FocusStatus.STAGE_ERROR, f"Fine scan: {e}", coarse=coarse)
        except OutOfRangeError as e:
            return self._result_error(FocusStatus.OUT_OF_RANGE, f"Fine scan: {e}", coarse=coarse)

        # 7. Validate fine curve the same way.
        if len(fine.points) < 3:
            return self._result_error(
                FocusStatus.NO_PEAK,
                "Too few fine scan points to find a peak.",
                coarse=coarse, fine=fine,
            )
        fine_scores = [p.score for p in fine.points]
        fine_argmax = max(range(len(fine.points)), key=lambda k: fine_scores[k])
        if fine_argmax == 0 or fine_argmax == len(fine.points) - 1:
            return self._result_error(
                FocusStatus.NO_PEAK,
                "Peak at edge of fine scan range; coarse peak may have been a shoulder.",
                coarse=coarse, fine=fine,
            )

        # 8. Sub-step peak estimate.
        z_best = scanner.estimate_peak(fine)
        if z_best is None:
            z_best = fine.best().z_um

        # 9. Final positioning: approach the best Z from above, then move down to target.
        pre_z = min(z_best + params.backlash_um, params.z_max_um)
        scanner._set_stage_tolerance(params.final_stage_tolerance_um)
        try:
            if pre_z > z_best:
                self.stage.move_absolute_um(pre_z)
                self.stage.wait_settled(params.stage_timeout_ms)
            self.stage.move_absolute_um(z_best)
            self.stage.wait_settled(params.stage_timeout_ms)
        except (StageTimeoutError, StageError) as e:
            return self._result_error(
                FocusStatus.STAGE_ERROR, f"Final move: {e}", coarse=coarse, fine=fine
            )

        # 10. Final verification sample.
        try:
            final_point = scanner.score_current_position(roi)
        except FrameTimeoutError as e:
            return self._result_error(
                FocusStatus.FRAME_ERROR, f"Final verification: {e}", coarse=coarse, fine=fine
            )
        except (StageTimeoutError, StageError) as e:
            return self._result_error(
                FocusStatus.STAGE_ERROR, f"Final verification: {e}", coarse=coarse, fine=fine
            )

        fine_best_score = fine.best().score
        if final_point.score < 0.7 * fine_best_score:
            return FocusResult(
                status=FocusStatus.LOW_CONFIDENCE,
                z_best_um=final_point.z_um,
                final_score=final_point.score,
                confidence=0.0,
                coarse=coarse, fine=fine,
                message=(
                    f"Final score {final_point.score:.4f} regressed below 70% of "
                    f"fine-scan best {fine_best_score:.4f}"
                ),
            )

        # 11. Compute confidence in [0, 1].
        c = 1.0
        if low_confidence_saturation:
            c *= 0.5
        c *= min(1.0, prominence)
        c = max(0.0, min(1.0, c))
        if c < params.min_confidence:
            status = FocusStatus.LOW_CONFIDENCE
            message = f"Confidence {c:.2f} below threshold {params.min_confidence:.2f}"
        else:
            status = FocusStatus.OK
            message = ""

        # 12. Return result.
        return FocusResult(
            status=status,
            z_best_um=final_point.z_um,
            final_score=final_point.score,
            confidence=c,
            coarse=coarse,
            fine=fine,
            message=message,
        )

"""Z-axis scanning routines: coarse scan, fine scan, parabolic peak fitting."""

import time
import statistics
from typing import Callable, Optional
import numpy as np
from autofocus.models import (
    ROI, Frame, FrameProvider, ZStage, FocusStrategy,
    AutofocusParams, FocusPoint, ScanCurve, FrameRetentionProvider,
)
from autofocus.exceptions import OutOfRangeError
from autofocus.roi import saturation_ratio, crop, to_grayscale


def parabolic_peak(zs: list[float], scores: list[float]) -> Optional[float]:
    """Fit a parabola to three points and return the interpolated peak Z."""
    if len(zs) < 3 or len(scores) < 3:
        return None
    coeffs = np.polyfit(np.asarray(zs, dtype=float), np.asarray(scores, dtype=float), deg=2)
    a = float(coeffs[0])
    b = float(coeffs[1])
    if abs(a) < 1e-12 or a >= 0:
        return None
    z_peak = -b / (2.0 * a)
    lo = min(zs)
    hi = max(zs)
    if z_peak < lo or z_peak > hi:
        return None
    return z_peak


class ZScanner:
    """Drives Z-axis scans and computes per-Z sharpness scores."""

    def __init__(
        self,
        stage: ZStage,
        frames: FrameProvider,
        strategy: FocusStrategy,
        params: AutofocusParams,
    ):
        self.stage = stage
        self.frames = frames
        self.strategy = strategy
        self.params = params

    def _set_stage_tolerance(self, tolerance_um: float) -> None:
        setter = getattr(self.stage, "set_target_tolerance_um", None)
        if callable(setter):
            setter(float(tolerance_um))

    def sample_score(self, z_um: float, roi: ROI, tolerance_um: float | None = None) -> FocusPoint:
        """Move to z_um, acquire frames_per_z frames, and return the median sharpness and saturation."""
        if not (self.params.z_min_um <= z_um <= self.params.z_max_um):
            raise OutOfRangeError(
                f"z={z_um} outside [{self.params.z_min_um}, {self.params.z_max_um}]"
            )
        if tolerance_um is not None:
            self._set_stage_tolerance(tolerance_um)
        self.stage.move_absolute_um(z_um)
        self.stage.wait_settled(self.params.stage_timeout_ms)
        return self.score_current_position(roi)

    def score_current_position(self, roi: ROI) -> FocusPoint:
        """Acquire frames at the current stage position and return the median score."""
        actual_z_um = self.stage.get_position_um()
        if self.params.settle_ms > 0:
            time.sleep(self.params.settle_ms / 1000.0)
        t_after = time.monotonic()
        captured_frames: list[Frame] = []
        scores_list: list[float] = []
        sat_list: list[float] = []
        for _ in range(self.params.frames_per_z):
            frame = self.frames.wait_for_next(
                after_ts=t_after, timeout_ms=self.params.frame_timeout_ms
            )
            t_after = frame.timestamp
            captured_frames.append(frame)
            scores_list.append(self.strategy.score(frame.image, roi))
            sat_patch = to_grayscale(crop(frame.image, roi))
            sat_list.append(saturation_ratio(sat_patch))
        median_score = statistics.median(scores_list)
        median_saturation = statistics.median(sat_list)
        retention_provider = (
            self.frames if isinstance(self.frames, FrameRetentionProvider) else None
        )
        if retention_provider is not None and captured_frames:
            keep_index = min(
                range(len(captured_frames)),
                key=lambda idx: (abs(scores_list[idx] - median_score), abs(sat_list[idx] - median_saturation), idx),
            )
            retention_provider.retain_only(captured_frames, captured_frames[keep_index])
        return FocusPoint(
            z_um=actual_z_um,
            score=median_score,
            saturation_ratio=median_saturation,
        )

    def _scan(
        self,
        center_um: float,
        roi: ROI,
        range_um: float,
        step_um: float,
        phase: str,
        on_progress: Optional[Callable[[FocusPoint], None]],
        tolerance_um: float,
    ) -> ScanCurve:
        """Run a single scan phase over [center-range, center+range] at the given step size."""
        z_lo = max(center_um - range_um, self.params.z_min_um)
        z_hi = min(center_um + range_um, self.params.z_max_um)
        grid = [
            float(z)
            for z in np.arange(z_hi, z_lo - step_um * 0.5, -step_um)
            if z >= z_lo
        ]
        # Approach z_hi from above so all measurements are made while moving downward.
        current = self.stage.get_position_um()
        if current <= z_hi:
            pre_z = min(z_hi + self.params.backlash_um, self.params.z_max_um)
            if pre_z > current:
                self.stage.move_absolute_um(pre_z)
                self.stage.wait_settled(self.params.stage_timeout_ms)
        points: list[FocusPoint] = []
        for z in grid:
            point = self.sample_score(z, roi, tolerance_um=tolerance_um)
            points.append(point)
            if on_progress is not None:
                on_progress(point)
        return ScanCurve(phase=phase, points=points)

    def coarse_scan(
        self,
        center_um: float,
        roi: ROI,
        on_progress: Optional[Callable[[FocusPoint], None]] = None,
    ) -> ScanCurve:
        """Run the coarse scan centred at center_um and return the scored curve."""
        return self._scan(
            center_um, roi,
            self.params.coarse_range_um, self.params.coarse_step_um,
            "coarse", on_progress, self.params.coarse_stage_tolerance_um,
        )

    def fine_scan(
        self,
        center_um: float,
        roi: ROI,
        on_progress: Optional[Callable[[FocusPoint], None]] = None,
    ) -> ScanCurve:
        """Run the fine scan centred at center_um and return the scored curve."""
        return self._scan(
            center_um, roi,
            self.params.fine_range_um, self.params.fine_step_um,
            "fine", on_progress, self.params.fine_stage_tolerance_um,
        )

    def estimate_peak(self, curve: ScanCurve) -> Optional[float]:
        """Return the sub-step peak Z via parabolic interpolation, or the raw argmax if fitting fails."""
        points = curve.points
        if not points:
            return None
        i = max(range(len(points)), key=lambda k: points[k].score)
        if i == 0 or i == len(points) - 1:
            return points[i].z_um
        three = [points[i - 1], points[i], points[i + 1]]
        z_peak = parabolic_peak(
            [p.z_um for p in three],
            [p.score for p in three],
        )
        if z_peak is None:
            return points[i].z_um
        return float(np.clip(z_peak, self.params.z_min_um, self.params.z_max_um))
